const DT = 1 / 60;
let prev = 0, lag = 0, running = true;
const frame: FrameRequestCallback = (ts) => {
  if (!running) return;
  if (prev !== 0) {
    lag += (ts - prev) / 1000;             // DOMHighResTimeStamp is milliseconds
    if (lag > 0.25) lag = 0.25;
    while (lag >= DT) { step(DT); lag -= DT; }
    render(lag / DT);
  }
  prev = ts;
  requestAnimationFrame(frame);            // one-shot API: re-arm explicitly
};
requestAnimationFrame(frame);

