function frame(): void {
  const now = performance.now();
  lag += (now - prev) / 1000; prev = now;   // monotonic; wall clock would jump
  if (lag > 0.25) lag = 0.25;               // clamp
  while (lag >= DT) { world.step(DT); lag -= DT; }
  render(lag / DT);
  setTimeout(frame, Math.max(0, (DT * 1000) / 2)); // pacing hint only
